window.CODE = Object.assign(window.CODE || {}, {"ch44/acceptance_spec.py":"\"\"\"The acceptance spec for the task, written from the PLAN and kept OUTSIDE the repository the coder can edit.\n\nThe coder writes its own tests, and a coder under pressure can weaken them. This file is the planner's\ndefinition of done. It is run against the coder's branch by the pipeline: the coder never sees or changes it.\n\n    python -m pytest -q acceptance_spec.py        (run from inside the repository to check)\n\"\"\"\nimport pytest\nfrom helpdesk_lookup import doctors_on\n\n\n@pytest.mark.parametrize(\"day\", [\"Thu\", \"thu\", \"THU\", \" thursday \", \"Thursday\"])\ndef test_day_spellings_are_accepted(day):\n    r = doctors_on(day)\n    assert r[\"day\"] == \"Thu\"\n    assert [d[\"name\"] for d in r[\"doctors\"]] == [\"Dr Iyer\", \"Dr Rao\"]          # sorted by name\n\n\ndef test_each_doctor_carries_the_department():\n    assert {\"name\": \"Dr Khan\", \"department\": \"paediatrics\"} in doctors_on(\"Mon\")[\"doctors\"]\n\n\ndef test_department_filter():\n    r = doctors_on(\"Mon\", \"cardiology\")\n    assert r[\"doctors\"] == [{\"name\": \"Dr Mehta\", \"department\": \"cardiology\"}]\n\n\ndef test_a_day_nobody_works_is_empty_not_an_error():\n    assert doctors_on(\"Sat\") == {\"day\": \"Sat\", \"doctors\": []}\n\n\n@pytest.mark.parametrize(\"bad\", [\"Sun\", \"Funday\", \"\", \"   \", \"Mondo\", \"Th\"])\ndef test_unknown_day_is_an_error_not_a_crash(bad):\n    r = doctors_on(bad)\n    assert \"error\" in r and r[\"known_days\"][0] == \"Mon\"\n\n\ndef test_unknown_department_matches_the_existing_error():\n    assert doctors_on(\"Mon\", \"dermatology\") == {\"error\": \"Unknown department 'dermatology'.\", \"known_departments\": [\"cardiology\", \"orthopaedics\", \"paediatrics\"]}\n","ch44/base_project/AGENTS.md":"# City Clinic helpdesk lookups\n\n- Run tests: `python -m pytest -q`\n- Code is in `helpdesk_lookup.py`; data is in `clinic_data.py`. Do not edit the data.\n- Lookups return plain dicts and never raise on bad input.\n- Add a test for every new function, written first.\n- Never edit `requirements.txt` without asking.\n","ch44/base_project/clinic_data.py":"\"\"\"Made-up City Clinic data (the same doctors as Chapters 9 and 27). Nothing here knows about AI.\"\"\"\n\nSCHEDULE = {\n    \"cardiology\": {\"Dr Mehta\": [\"Mon\", \"Wed\"], \"Dr Rao\": [\"Thu\", \"Fri\"]},\n    \"orthopaedics\": {\"Dr Iyer\": [\"Tue\", \"Thu\"]},\n    \"paediatrics\": {\"Dr Khan\": [\"Mon\", \"Tue\", \"Fri\"]},\n}\nDAYS = [\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Sat\"]\n","ch44/base_project/helpdesk_lookup.py":"\"\"\"Read-only lookups the helpdesk uses. Everything returns plain dicts and never raises on bad input.\"\"\"\nfrom clinic_data import SCHEDULE\n\n\ndef doctor_schedule(department: str) -> dict:\n    \"\"\"Which doctors in a department see patients on which weekdays.\"\"\"\n    dept = SCHEDULE.get(department.strip().lower())\n    if dept is None:\n        return {\"error\": f\"Unknown department '{department}'.\", \"known_departments\": list(SCHEDULE)}\n    return {\"department\": department.strip().lower(), \"doctors\": dept}\n","ch44/base_project/requirements.txt":"pytest==9.1.1\n","ch44/base_project/test_lookup.py":"from helpdesk_lookup import doctor_schedule\n\n\ndef test_known_department():\n    r = doctor_schedule(\"Cardiology \")\n    assert r[\"department\"] == \"cardiology\"\n    assert r[\"doctors\"][\"Dr Mehta\"] == [\"Mon\", \"Wed\"]\n    assert \"Dr Rao\" in r[\"doctors\"]\n\n\ndef test_unknown_department_is_an_error_not_a_crash():\n    r = doctor_schedule(\"dermatology\")\n    assert \"error\" in r\n    assert \"cardiology\" in r[\"known_departments\"]\n","ch44/db_check.py":"\"\"\"Does the new feature agree with the clinic database? Asked through the REAL read-only MCP server of Chapter 41.\n\nThe check starts readonly_db_server.py as a child process (exactly how Claude Code would), asks it for the\ndoctors table over MCP, builds 'who works on each weekday' from the rows, and compares that with what the\nfeature returns for every weekday. Code and data drifting apart is a classic way for a helpdesk to give a\npatient the wrong day.\n\"\"\"\nfrom __future__ import annotations\n\nimport asyncio\nimport json\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nfrom mcp import ClientSession, StdioServerParameters\nfrom mcp.client.stdio import stdio_client\n\nCH41 = Path(__file__).resolve().parent.parent / \"ch41\"\nDAYS = [\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Sat\"]\n\n\nasync def _rows(db_path: str) -> list[list]:\n    params = StdioServerParameters(command=sys.executable, args=[str(CH41 / \"readonly_db_server.py\")], env={\"CLINIC_DB\": db_path, \"PATH\": \"/usr/bin:/bin\"})\n    async with stdio_client(params) as (r, w):\n        async with ClientSession(r, w) as s:\n            await s.initialize()\n            res = await s.call_tool(\"query\", {\"sql\": \"SELECT name, department, days FROM doctors ORDER BY name\"})\n            return json.loads(res.content[0].text)[\"rows\"]\n\n\ndef db_doctors(db_path: str) -> dict[str, list[dict]]:\n    by_day = {d: [] for d in DAYS}\n    for name, dept, days in asyncio.run(_rows(db_path)):\n        for d in days.split(\",\"):\n            if d.strip() in by_day:\n                by_day[d.strip()].append({\"name\": name, \"department\": dept})\n    return {d: sorted(v, key=lambda x: x[\"name\"]) for d, v in by_day.items()}\n\n\ndef feature_doctors(repo: str) -> dict | str:\n    \"\"\"What the feature in `repo` returns for every weekday, or a one-line error.\"\"\"\n    code = \"import json; from helpdesk_lookup import doctors_on; print(json.dumps({d: doctors_on(d) for d in %r}))\" % (DAYS,)\n    p = subprocess.run([sys.executable, \"-c\", code], cwd=repo, capture_output=True, text=True, timeout=30, env={\"PATH\": \"/usr/bin:/bin\", \"PYTHONDONTWRITEBYTECODE\": \"1\"})\n    if p.returncode != 0:\n        return \"the feature could not be called: \" + (p.stderr.strip().splitlines() or [\"?\"])[-1]\n    return json.loads(p.stdout)\n\n\ndef check(repo: str, db_path: str) -> list[str]:\n    \"\"\"Mismatches between database and feature. Empty list = they agree.\"\"\"\n    feat = feature_doctors(repo)\n    if isinstance(feat, str):\n        return [feat]\n    db = db_doctors(db_path)\n    out = []\n    for d in DAYS:\n        got = feat[d].get(\"doctors\") if isinstance(feat[d], dict) else None\n        if got != db[d]:\n            out.append(f\"{d}: database says {[x['name'] for x in db[d]]}, feature says {[x['name'] for x in got] if got is not None else feat[d]}\")\n    return out\n\n\nif __name__ == \"__main__\":\n    print(\"\\n\".join(check(sys.argv[1], sys.argv[2])) or \"database and feature agree\")\n","ch44/pipeline.py":"\"\"\"The capstone: a team builds one feature for the Clinic Helpdesk, with every safeguard of Part G switched on.\n\n    python pipeline.py            # offline; the roles are stand-ins (see roles.py)\n    python pipeline.py --ask      # ask YOU at the two human checkpoints\n    python pipeline.py --pypi     # also ask pypi.org whether new packages exist\n\nFlow (each box is real code you have already met):\n\n  planner -> [person approves plan] -> coder in its own worktree -> tester (project tests, gate, acceptance spec,\n  database check over MCP) -> reviewer verdict -> if rejected: next attempt (max N) / else a person decides\n  -> [person approves merge] -> merge -> tests again on main.\n\nThe pipeline never merges on its own: a person's yes is a function argument, and a missing yes means no.\n\"\"\"\nfrom __future__ import annotations\n\nimport subprocess\nimport sys\nimport tempfile\nfrom dataclasses import dataclass, field\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nfor sub in (\"ch39\", \"ch40\", \"ch41\", \"ch42\", \"ch43\"):\n    sys.path.insert(0, str(HERE.parent / sub))\nsys.path.insert(0, str(HERE))\n\nimport clinic_db  # noqa: E402  (Chapter 41)\nimport db_check  # noqa: E402\nimport dep_check  # noqa: E402  (Chapter 43)\nimport gate  # noqa: E402  (Chapter 43)\nimport handoff  # noqa: E402  (Chapter 42)\nimport roles  # noqa: E402\nimport team_budget  # noqa: E402\nimport worktrees  # noqa: E402  (Chapter 42)\n\nPYTEST = f\"{sys.executable} -m pytest -q -p no:cacheprovider\"\nAPPROVED = dep_check.load_approved((HERE.parent / \"ch43\" / \"approved-packages.txt\").read_text())\n\n\n@dataclass\nclass Result:\n    merged: bool = False\n    status: str = \"started\"                 # merged | needs_human | rejected_by_person | budget\n    log: list[str] = field(default_factory=list)\n    attempts: list[dict] = field(default_factory=list)\n    notes: list = field(default_factory=list)\n    budget: team_budget.Budget | None = None\n\n    def say(self, line: str, echo: bool = True):\n        self.log.append(line)\n        if echo:\n            print(line)\n\n\ndef _run(cmd: str, cwd: str) -> tuple[int, str]:\n    p = subprocess.run(cmd.split(), cwd=cwd, capture_output=True, text=True, timeout=120, env={\"PATH\": \"/usr/bin:/bin:/usr/local/bin\", \"PYTHONDONTWRITEBYTECODE\": \"1\"})\n    out = (p.stdout + p.stderr).strip().splitlines()\n    return p.returncode, (out[-1] if out else \"\")\n\n\ndef make_base_repo(root: str) -> str:\n    \"\"\"Copy base_project into root/clinic and commit it on main.\"\"\"\n    repo = Path(root) / \"clinic\"\n    repo.mkdir(parents=True)\n    for f in (HERE / \"base_project\").iterdir():\n        if f.is_file():\n            (repo / f.name).write_text(f.read_text())\n    worktrees.git(repo, \"init\", \"-q\", \"-b\", \"main\")\n    worktrees.git(repo, \"add\", \"-A\")\n    worktrees.git(repo, \"-c\", \"user.name=agent\", \"-c\", \"user.email=agent@example.com\", \"commit\", \"-qm\", \"base\")\n    return str(repo)\n\n\ndef run_pipeline(workdir: str, task: str = roles.TASK, attempts=None, max_attempts: int = 3, max_tokens: int = 200_000,\n                 approve_plan=lambda plan: True, approve_merge=lambda summary: True, use_pypi: bool = False, echo: bool = True) -> Result:\n    attempts = attempts if attempts is not None else roles.ATTEMPTS\n    res = Result(budget=team_budget.Budget(max_tokens))\n    say = lambda s: res.say(s, echo)  # noqa: E731\n    repo = make_base_repo(workdir)\n    db = clinic_db.create(str(Path(workdir) / \"clinic.db\"))\n    try:\n        # ---- 1. planner\n        plan, read = roles.planner(task, repo)\n        res.budget.spend(\"planner\", \"read repo, write plan\", read + task, plan.to_markdown())\n        n1 = handoff.Handoff(task=plan.task, from_role=\"planner\", to_role=\"coder\", goal=plan.goal, done=[\"read the code and wrote the plan\"],\n                             decisions=[\"tests are written first and must fail\", \"acceptance_spec.py is the definition of done and the coder cannot edit it\"],\n                             files_changed=[], verify=[PYTEST], evidence=\"\", open_questions=[], risks=[])\n        problems = handoff.validate(n1)\n        res.notes.append(n1)\n        say(f\"[planner] plan for {plan.task}: owns {plan.owned}; handoff problems: {problems or 'none'}\")\n        if not approve_plan(plan):\n            res.status = \"rejected_by_person\"\n            say(\"[person] plan REJECTED. Nothing was built.\")\n            return res\n        say(\"[person] plan approved.\")\n\n        # ---- 2. attempts\n        for i in range(min(max_attempts, len(attempts))):\n            name = f\"attempt{i + 1}\"\n            wt = worktrees.add_worktree(repo, name, \"main\")\n            record = {\"attempt\": i + 1}\n            try:\n                red_green = \"n/a\"\n                written = \"\"\n                for ph in attempts[i]:\n                    for rel, text in ph.files.items():\n                        (wt / rel).write_text(text)\n                        written += text\n                    worktrees.commit_all(wt, ph.message)\n                    if ph.expect:\n                        code, last = _run(PYTEST, str(wt))\n                        ok = (code != 0) if ph.expect == \"fail\" else (code == 0)\n                        say(f\"[coder #{i + 1}] {ph.message}: tests {'failed' if code else 'passed'} ({last}) -> expected {ph.expect}: {'ok' if ok else 'NOT as expected'}\")\n                        red_green = \"red-green\" if ok and ph.expect == \"pass\" and red_green != \"no-red\" else red_green\n                        if ph.expect == \"fail\" and not ok:\n                            red_green = \"no-red\"\n                if len(attempts[i]) == 1:\n                    red_green = \"no-red\"\n                    say(f\"[coder #{i + 1}] wrote tests and code in one step: no red step observed.\")\n                res.budget.spend(\"coder\", f\"attempt {i + 1}\", plan.to_markdown() + read, written)\n\n                changed = worktrees.changed_files(wt, \"main\")\n                outside = worktrees.violations(plan.owned, changed)\n                say(f\"[coder #{i + 1}] changed {changed}; outside the plan: {outside or 'none'}\")\n\n                checks = gate.run_gate(str(wt), \"main\", PYTEST, APPROVED, use_pypi)\n                gate_status = {c.name: c.status for c in checks}\n                acc_code, acc_last = _run(f\"{sys.executable} -m pytest -q -p no:cacheprovider {HERE / 'acceptance_spec.py'}\", str(wt))\n                db_mismatch = db_check.check(str(wt), db)\n                diff = worktrees.git(wt, \"diff\", \"main...HEAD\").stdout\n                res.budget.spend(\"tester\", f\"attempt {i + 1}: gate+spec+db\", diff, gate.render(checks))\n                say(f\"[tester #{i + 1}] gate: \" + \", \".join(f\"{k}={v}\" for k, v in gate_status.items()))\n                say(f\"[tester #{i + 1}] acceptance spec: {'pass' if acc_code == 0 else 'FAIL'} ({acc_last}); database check: {'agrees' if not db_mismatch else str(len(db_mismatch)) + ' mismatch(es)'}\")\n\n                tests_note = next((c.notes[0] for c in checks if c.name == \"tests\" and c.notes), \"\")\n                n2 = handoff.Handoff(task=plan.task, from_role=\"coder\", to_role=\"reviewer\", goal=plan.goal,\n                                     done=[f\"implemented doctors_on (attempt {i + 1})\"], decisions=[\"accepts full and short weekday names, case-insensitive\"],\n                                     files_changed=changed, verify=[PYTEST], evidence=tests_note, risks=[], tokens_used=res.budget.tokens)\n                hp = handoff.validate(n2, plan.owned)\n                res.notes.append(n2)\n                verdict = roles.reviewer({\"gate\": gate_status, \"outside_owned\": outside, \"acceptance\": \"pass\" if acc_code == 0 else \"fail\",\n                                          \"db_mismatches\": db_mismatch, \"handoff_problems\": hp, \"red_green\": red_green})\n                res.budget.spend(\"reviewer\", f\"attempt {i + 1}: verdict\", diff + n2.to_markdown(), str(verdict))\n                record.update(verdict=verdict.approve, reasons=verdict.reasons, gate=gate_status, red_green=red_green)\n                res.attempts.append(record)\n                say(f\"[reviewer #{i + 1}] {verdict}\")\n                if verdict.approve:\n                    summary = f\"{len(changed)} file(s): {changed}; gate passed; acceptance spec passed; database agrees; tests were written first.\"\n                    if not approve_merge(summary):\n                        res.status = \"rejected_by_person\"\n                        say(\"[person] merge DECLINED. main is untouched.\")\n                        worktrees.remove_worktree(repo, wt)\n                        return res\n                    say(\"[person] merge approved.\")\n                    clean, conflicts = worktrees.merge_branch(repo, f\"worktree-{name}\")\n                    worktrees.remove_worktree(repo, wt, f\"worktree-{name}\")\n                    code, last = _run(PYTEST, repo)\n                    say(f\"[main] merged cleanly: {clean}; tests on main afterwards: {'pass' if code == 0 else 'FAIL'} ({last})\")\n                    res.merged, res.status = clean and code == 0, \"merged\" if clean and code == 0 else \"needs_human\"\n                    return res\n                say(f\"[pipeline] attempt {i + 1} rejected. The worktree is thrown away; the next attempt starts from main.\")\n            finally:\n                if wt.exists():\n                    worktrees.remove_worktree(repo, wt, f\"worktree-{name}\")\n        res.status = \"needs_human\"\n        say(f\"[pipeline] no attempt was accepted after {len(res.attempts)} tries. A person must take over.\")\n        return res\n    except team_budget.BudgetExceeded as e:\n        res.status = \"budget\"\n        say(f\"[budget] STOPPED: {e}\")\n        return res\n\n\nif __name__ == \"__main__\":\n    a = sys.argv[1:]\n    ask = \"--ask\" in a\n    yes = lambda q: input(f\"[person] {q} [y/N] \").strip().lower() == \"y\"  # noqa: E731\n    with tempfile.TemporaryDirectory() as tmp:\n        r = run_pipeline(tmp, approve_plan=(lambda p: yes(\"Approve this plan?\\n\" + p.to_markdown())) if ask else (lambda p: True),\n                         approve_merge=(lambda s: yes(f\"Merge? {s}\")) if ask else (lambda s: True), use_pypi=\"--pypi\" in a)\n        print(\"\\n\" + r.budget.report())\n        print(f\"\\nRESULT: {r.status}\")\n","ch44/README.md":"# Chapter 44: capstone, a team builds a feature for the Clinic Helpdesk\n\nOne command builds a real feature in a real git repository using a team of STAND-IN roles, with the safeguards of Part G around them.\n\n```bash\npython pipeline.py            # offline; about 3 seconds\npython pipeline.py --ask      # you answer the two human checkpoints\npython pipeline.py --pypi     # also asks pypi.org whether new packages exist\npython -m pytest -q           # 20 tests, about a minute (each starts git and an MCP server)\n```\n\n| File | Role | Status |\n|---|---|---|\n| `base_project/` | The existing helpdesk lookups: data, one function, two tests, AGENTS.md | real code |\n| `acceptance_spec.py` | The planner's definition of done. Lives OUTSIDE the repo; the coder cannot edit it | real tests |\n| `roles.py` | Planner, coder (two pre-written attempts), reviewer (fixed rules) | **STAND-INS, no AI model** |\n| `team_budget.py` | One token and cost budget for the whole team; stops when it is gone | real mechanism; numbers are ESTIMATES from text size |\n| `db_check.py` | Compares the feature with the clinic database, asked through the real read-only MCP server (ch41) | real |\n| `pipeline.py` | Orchestration: worktrees (ch42), handoff notes (ch42), gate (ch43), checkpoints | real |\n\nThe git worktrees, the project's tests, the gate, the acceptance spec, the MCP database query and the merge are all real. What is not real is the intelligence of the coder: swap `roles.py` for subagents (Chapter 42's `starter/.claude/agents/`) and everything around it stays the same.\n","ch44/roles.py":"\"\"\"STAND-IN roles for the capstone team: planner, coder, reviewer.\n\nIn a real team each of these is a Claude Code subagent (Chapter 42) that reads and writes through a model.\nHere they are small, fixed programs so that the whole pipeline can run offline, repeatably and for free:\n\n  * the planner reads the real project files and writes a real plan;\n  * the coder has two PRE-WRITTEN attempts: a careless one and a careful one. Nothing here reads the\n    gate's feedback: the pipeline simply asks for the next attempt, as a real coder would after a failure;\n  * the reviewer turns the evidence into a verdict by fixed rules.\n\nEverything AROUND the roles is real: git worktrees, the project's tests, the gate, the acceptance spec,\nthe database check over MCP, the handoff validation, the budget.\n\"\"\"\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom pathlib import Path\n\nTASK = (\"Add doctors_on(day, department=None) to helpdesk_lookup.py. It returns the doctors who see patients on a weekday, \"\n        \"as {'day': 'Thu', 'doctors': [{'name', 'department'}]} sorted by name. It accepts 'thu', 'Thursday' and ' THU '. \"\n        \"An unknown day returns {'error', 'known_days'}; an unknown department returns the same error as doctor_schedule. \"\n        \"It must agree with the clinic database.\")\n\n\n@dataclass\nclass Plan:\n    task: str\n    goal: str\n    owned: list[str]\n    steps: list[str]\n    acceptance: list[str]\n    risks: list[str] = field(default_factory=list)\n\n    def to_markdown(self) -> str:\n        def b(items):\n            return \"\\n\".join(f\"- {i}\" for i in items)\n        return (f\"# Plan\\n\\n**Goal:** {self.goal}\\n\\n## Files this task owns\\n{b(self.owned)}\\n\\n## Steps\\n{b(self.steps)}\\n\\n\"\n                f\"## Done means\\n{b(self.acceptance)}\\n\\n## Risks\\n{b(self.risks) or '- none noted'}\\n\")\n\n\ndef planner(task: str, repo: str) -> tuple[Plan, str]:\n    \"\"\"Reads the real project files and returns (plan, the text it read, for the token estimate).\"\"\"\n    read = \"\"\n    for name in (\"AGENTS.md\", \"helpdesk_lookup.py\", \"clinic_data.py\", \"test_lookup.py\"):\n        read += (Path(repo) / name).read_text() + \"\\n\"\n    plan = Plan(\n        task=\"T-doctors-on\",\n        goal=\"Add a doctors_on(day, department) lookup to the helpdesk that agrees with the clinic database\",\n        owned=[\"helpdesk_lookup.py\", \"test_doctors_on.py\"],\n        steps=[\"Write test_doctors_on.py first and see it fail\", \"Implement doctors_on in helpdesk_lookup.py\", \"Run the project's tests\"],\n        acceptance=[\"acceptance_spec.py passes\", \"project tests pass and no existing test was weakened\", \"doctors_on matches the clinic database for every weekday\",\n                    \"no new dependency; clinic_data.py and requirements.txt untouched\"],\n        risks=[\"Day spelling variants\", \"A weekday with no doctors must be an empty list, not an error\"])\n    return plan, read\n\n\n@dataclass\nclass Phase:\n    message: str\n    files: dict[str, str]\n    expect: str | None = None          # \"fail\" = the tests must fail now (red); \"pass\" = must pass now (green); None = do not check\n\n\n# ---------------------------------------------------------------- attempt 1: careless\nCARELESS_IMPL = '''\"\"\"Read-only lookups the helpdesk uses. Everything returns plain dicts and never raises on bad input.\"\"\"\nfrom clinic_data import SCHEDULE\n\n\ndef doctor_schedule(department: str) -> dict:\n    \"\"\"Which doctors in a department see patients on which weekdays.\"\"\"\n    dept = SCHEDULE.get(department.strip().lower())\n    if dept is None:\n        return {\"error\": f\"Unknown department '{department}'.\", \"known_departments\": list(SCHEDULE)}\n    return {\"department\": department.strip().lower(), \"doctors\": dept}\n\n\ndef doctors_on(day, department=None):\n    out = []\n    for dept, docs in SCHEDULE.items():\n        for name, days in docs.items():\n            if day in days:\n                out.append({\"name\": name, \"department\": dept})\n    return {\"day\": day, \"doctors\": out}\n'''\nCARELESS_OLD_TEST = '''from helpdesk_lookup import doctor_schedule, doctors_on\n\n\ndef test_known_department():\n    r = doctor_schedule(\"Cardiology \")\n    assert r[\"department\"] == \"cardiology\"\n    assert r[\"doctors\"][\"Dr Mehta\"] == [\"Mon\", \"Wed\"]\n\n\ndef test_unknown_department_is_an_error_not_a_crash():\n    r = doctor_schedule(\"dermatology\")\n    assert \"error\" in r\n\n\ndef test_doctors_on():\n    assert doctors_on(\"Thu\")\n'''\nCARELESS = [Phase(\"add doctors_on\", {\"helpdesk_lookup.py\": CARELESS_IMPL, \"test_lookup.py\": CARELESS_OLD_TEST,\n                                     \"requirements.txt\": \"pytest==9.1.1\\nreqeusts==2.31.0\\n\"})]\n\n# ---------------------------------------------------------------- attempt 2: careful (tests first, then code)\nCAREFUL_TEST = '''import pytest\nfrom helpdesk_lookup import doctors_on\n\n\n@pytest.mark.parametrize(\"day\", [\"Thu\", \"thu\", \" THU \", \"Thursday\"])\ndef test_thursday_in_any_spelling(day):\n    r = doctors_on(day)\n    assert r[\"day\"] == \"Thu\"\n    assert [d[\"name\"] for d in r[\"doctors\"]] == [\"Dr Iyer\", \"Dr Rao\"]\n\n\ndef test_department_filter():\n    assert doctors_on(\"Mon\", \"Cardiology\")[\"doctors\"] == [{\"name\": \"Dr Mehta\", \"department\": \"cardiology\"}]\n\n\ndef test_empty_day_is_not_an_error():\n    assert doctors_on(\"Sat\")[\"doctors\"] == []\n\n\n@pytest.mark.parametrize(\"bad\", [\"Sun\", \"\", \"Funday\", \"Th\"])\ndef test_unknown_day_is_an_error(bad):\n    assert \"error\" in doctors_on(bad)\n\n\ndef test_unknown_department_is_an_error():\n    assert \"error\" in doctors_on(\"Mon\", \"dermatology\")\n'''\nCAREFUL_IMPL = '''\"\"\"Read-only lookups the helpdesk uses. Everything returns plain dicts and never raises on bad input.\"\"\"\nfrom clinic_data import DAYS, SCHEDULE\n\n_FULL = {\"Mon\": \"monday\", \"Tue\": \"tuesday\", \"Wed\": \"wednesday\", \"Thu\": \"thursday\", \"Fri\": \"friday\", \"Sat\": \"saturday\"}\n_DAY_LOOKUP = {**{d.lower(): d for d in DAYS}, **{full: d for d, full in _FULL.items()}}\n\n\ndef doctor_schedule(department: str) -> dict:\n    \"\"\"Which doctors in a department see patients on which weekdays.\"\"\"\n    dept = SCHEDULE.get(department.strip().lower())\n    if dept is None:\n        return {\"error\": f\"Unknown department '{department}'.\", \"known_departments\": list(SCHEDULE)}\n    return {\"department\": department.strip().lower(), \"doctors\": dept}\n\n\ndef doctors_on(day: str, department: str | None = None) -> dict:\n    \"\"\"Doctors who see patients on a weekday ('Thu', 'thursday', ' THU '), optionally in one department.\"\"\"\n    d = _DAY_LOOKUP.get(day.strip().lower())\n    if d is None:\n        return {\"error\": f\"Unknown day '{day}'.\", \"known_days\": DAYS}\n    if department is None:\n        departments = SCHEDULE\n    else:\n        found = doctor_schedule(department)\n        if \"error\" in found:\n            return found\n        departments = {found[\"department\"]: found[\"doctors\"]}\n    doctors = [{\"name\": name, \"department\": dept} for dept, docs in departments.items() for name, days in docs.items() if d in days]\n    return {\"day\": d, \"doctors\": sorted(doctors, key=lambda x: x[\"name\"])}\n'''\nCAREFUL = [Phase(\"tests first: doctors_on\", {\"test_doctors_on.py\": CAREFUL_TEST}, expect=\"fail\"),\n           Phase(\"implement doctors_on\", {\"helpdesk_lookup.py\": CAREFUL_IMPL}, expect=\"pass\")]\n\nATTEMPTS = [CARELESS, CAREFUL]\n\n\n# ---------------------------------------------------------------- reviewer\n@dataclass\nclass Verdict:\n    approve: bool\n    reasons: list[str]\n\n    def __str__(self):\n        return \"APPROVE\" if self.approve else \"REQUEST CHANGES:\\n\" + \"\\n\".join(f\"  {i}. {r}\" for i, r in enumerate(self.reasons, 1))\n\n\ndef reviewer(evidence: dict) -> Verdict:\n    \"\"\"Fixed rules over the evidence the pipeline collected. A real reviewer also reads the diff for design and risk.\"\"\"\n    reasons = []\n    for name, status in evidence[\"gate\"].items():\n        if status == \"fail\":\n            reasons.append(f\"gate check '{name}' failed\")\n    if evidence[\"outside_owned\"]:\n        reasons.append(f\"changed files the plan did not allow: {evidence['outside_owned']}\")\n    if evidence[\"acceptance\"] != \"pass\":\n        reasons.append(\"the acceptance spec does not pass\")\n    if evidence[\"db_mismatches\"]:\n        reasons.append(f\"disagrees with the clinic database: {evidence['db_mismatches'][:2]}\")\n    if evidence[\"handoff_problems\"]:\n        reasons.append(f\"handoff note is not acceptable: {evidence['handoff_problems']}\")\n    if evidence[\"red_green\"] == \"no-red\":\n        reasons.append(\"the tests never failed before the code was written, so they may not test anything\")\n    return Verdict(not reasons, reasons)\n","ch44/team_budget.py":"\"\"\"A token and cost budget for a team of helpers. An ESTIMATE from text size, not a bill.\n\nWhy estimates: in this tutorial the roles are stand-ins, so no model reports real usage. We reuse Chapter 40's\nrule of thumb (about 3.5 characters per token for code, 4 for prose) and Chapter 40's dated list prices, and we\nadd the cost that a real helper pays before it reads anything: a fresh context holding the system prompt, tool\ndefinitions and instruction files (Chapter 40 uses 20,000 tokens; set your own with ctx_budget.py).\n\nThe point is the MECHANISM: every helper spends against one budget, and the pipeline stops and asks a person\nwhen the budget is gone, instead of letting a loop run on.\n\"\"\"\nfrom __future__ import annotations\n\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent / \"ch40\"))\nfrom cost_model import PRICES  # noqa: E402  (Chapter 40)\nfrom ctx_budget import estimate_tokens  # noqa: E402\n\nSTART_CONTEXT = 20_000\nMODELS = {\"planner\": \"sonnet-5.5\", \"coder\": \"sonnet-5.5\", \"tester\": \"haiku-5.5\", \"reviewer\": \"sonnet-5.5\"}\n\n\nclass BudgetExceeded(Exception):\n    pass\n\n\nclass Budget:\n    def __init__(self, max_tokens: int = 200_000):\n        self.max_tokens = max_tokens\n        self.rows: list[dict] = []\n\n    @property\n    def tokens(self) -> int:\n        return sum(r[\"in\"] + r[\"out\"] for r in self.rows)\n\n    @property\n    def dollars(self) -> float:\n        return sum(r[\"usd\"] for r in self.rows)\n\n    def spend(self, role: str, label: str, read_text: str, wrote_text: str) -> int:\n        m = PRICES[\"models\"][MODELS[role]]\n        tin = START_CONTEXT + estimate_tokens(read_text, \".py\")\n        tout = estimate_tokens(wrote_text, \".py\")\n        usd = tin * m[\"input\"] / 1e6 + tout * m[\"output\"] / 1e6\n        self.rows.append({\"role\": role, \"label\": label, \"model\": MODELS[role], \"in\": tin, \"out\": tout, \"usd\": usd})\n        if self.tokens > self.max_tokens:\n            raise BudgetExceeded(f\"token budget used up: {self.tokens:,} > {self.max_tokens:,} (after {role}: {label})\")\n        return tin + tout\n\n    def report(self) -> str:\n        lines = [f\"{'role':9} {'step':26} {'model':11} {'in':>7} {'out':>6} {'usd':>8}\"]\n        for r in self.rows:\n            lines.append(f\"{r['role']:9} {r['label'][:26]:26} {r['model']:11} {r['in']:>7,} {r['out']:>6,} {r['usd']:>8.4f}\")\n        lines.append(f\"{'TOTAL':9} {'':26} {'':11} {sum(r['in'] for r in self.rows):>7,} {sum(r['out'] for r in self.rows):>6,} {self.dollars:>8.4f}   (budget {self.max_tokens:,} tokens)\")\n        lines.append(\"ESTIMATE from text size + a 20,000-token starting context per helper call; list prices dated in ch40/prices.json.\")\n        return \"\\n\".join(lines)\n","ch44/test_ch44.py":"import subprocess\nimport sys\nfrom pathlib import Path\n\nimport pytest\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE))\nimport db_check  # noqa: E402\nimport pipeline  # noqa: E402\nimport roles  # noqa: E402\nimport team_budget  # noqa: E402\n\nsys.path.insert(0, str(HERE.parent / \"ch41\"))\nimport clinic_db  # noqa: E402\n\n\ndef run(tmp_path, **kw):\n    return pipeline.run_pipeline(str(tmp_path), echo=False, **kw)\n\n\n# ---------------------------------------------------------------- the whole pipeline\ndef test_careless_attempt_is_rejected_and_careful_one_is_merged(tmp_path):\n    r = run(tmp_path)\n    assert r.merged and r.status == \"merged\"\n    assert [a[\"verdict\"] for a in r.attempts] == [False, True]\n    first = \" \".join(r.attempts[0][\"reasons\"])\n    for needle in (\"diff-review\", \"dependencies\", \"plan did not allow\", \"acceptance spec\", \"clinic database\", \"never failed\"):\n        assert needle in first\n    assert r.attempts[1][\"red_green\"] == \"red-green\"\n\n\ndef test_main_really_has_the_feature_and_no_worktrees_are_left(tmp_path):\n    run(tmp_path)\n    repo = tmp_path / \"clinic\"\n    assert \"def doctors_on\" in (repo / \"helpdesk_lookup.py\").read_text()\n    assert (repo / \"test_doctors_on.py\").exists()\n    assert \"reqeusts\" not in (repo / \"requirements.txt\").read_text()                 # the careless attempt never reached main\n    listing = subprocess.run([\"git\", \"-C\", str(repo), \"worktree\", \"list\"], capture_output=True, text=True).stdout\n    assert len(listing.strip().splitlines()) == 1\n    assert subprocess.run([\"git\", \"-C\", str(repo), \"branch\", \"--list\", \"worktree-*\"], capture_output=True, text=True).stdout.strip() == \"\"\n\n\ndef test_the_careless_tests_really_do_pass_the_project_tests(tmp_path):\n    \"\"\"The point of the lesson: green tests alone would have approved attempt 1.\"\"\"\n    r = run(tmp_path)\n    assert r.attempts[0][\"gate\"][\"tests\"] == \"pass\" and r.attempts[0][\"gate\"][\"diff-review\"] == \"fail\"\n\n\ndef test_a_person_can_reject_the_plan(tmp_path):\n    r = run(tmp_path, approve_plan=lambda p: False)\n    assert r.status == \"rejected_by_person\" and not r.attempts\n    assert \"def doctors_on\" not in (tmp_path / \"clinic\" / \"helpdesk_lookup.py\").read_text()\n\n\ndef test_declining_the_merge_leaves_main_untouched(tmp_path):\n    r = run(tmp_path, approve_merge=lambda s: False)\n    assert r.status == \"rejected_by_person\" and not r.merged\n    assert \"def doctors_on\" not in (tmp_path / \"clinic\" / \"helpdesk_lookup.py\").read_text()\n\n\ndef test_the_merge_summary_given_to_the_person_names_the_files(tmp_path):\n    seen = []\n    run(tmp_path, approve_merge=lambda s: seen.append(s) or True)\n    assert \"helpdesk_lookup.py\" in seen[0] and \"test_doctors_on.py\" in seen[0]\n\n\ndef test_only_careless_attempts_end_with_a_human(tmp_path):\n    r = run(tmp_path, attempts=[roles.CARELESS, roles.CARELESS], max_attempts=2)\n    assert r.status == \"needs_human\" and not r.merged and len(r.attempts) == 2\n    assert \"def doctors_on\" not in (tmp_path / \"clinic\" / \"helpdesk_lookup.py\").read_text()\n\n\ndef test_max_attempts_is_respected(tmp_path):\n    r = run(tmp_path, max_attempts=1)\n    assert r.status == \"needs_human\" and len(r.attempts) == 1\n\n\ndef test_budget_stops_the_pipeline(tmp_path):\n    r = run(tmp_path, max_tokens=30_000)\n    assert r.status == \"budget\" and not r.merged\n    assert any(\"[budget] STOPPED\" in l for l in r.log)\n\n\ndef test_a_wrong_but_passing_implementation_is_caught_by_the_spec_the_coder_cannot_edit(tmp_path):\n    \"\"\"A coder that writes sloppy code AND matching sloppy tests is still caught by acceptance_spec.py.\"\"\"\n    sloppy_impl = roles.CARELESS_IMPL\n    sloppy_test = \"from helpdesk_lookup import doctors_on\\n\\n\\ndef test_it():\\n    assert doctors_on('Thu')['day'] == 'Thu'\\n\"\n    attempt = [roles.Phase(\"sloppy\", {\"helpdesk_lookup.py\": sloppy_impl, \"test_doctors_on.py\": sloppy_test})]\n    r = run(tmp_path, attempts=[attempt], max_attempts=1)\n    assert r.attempts[0][\"gate\"][\"tests\"] == \"pass\" and r.attempts[0][\"gate\"][\"diff-review\"] != \"fail\"\n    assert not r.attempts[0][\"verdict\"] and any(\"acceptance spec\" in x for x in r.attempts[0][\"reasons\"])\n\n\n# ---------------------------------------------------------------- pieces\ndef test_acceptance_spec_passes_on_the_careful_code_and_is_not_inside_the_repo(tmp_path):\n    repo = pipeline.make_base_repo(str(tmp_path))\n    (Path(repo) / \"helpdesk_lookup.py\").write_text(roles.CAREFUL_IMPL)\n    p = subprocess.run([sys.executable, \"-m\", \"pytest\", \"-q\", \"-p\", \"no:cacheprovider\", str(HERE / \"acceptance_spec.py\")], cwd=repo, capture_output=True, text=True)\n    assert p.returncode == 0, p.stdout[-400:]\n    assert not (Path(repo) / \"acceptance_spec.py\").exists()\n\n\ndef test_db_check_agrees_with_careful_code(tmp_path):\n    repo = pipeline.make_base_repo(str(tmp_path))\n    (Path(repo) / \"helpdesk_lookup.py\").write_text(roles.CAREFUL_IMPL)\n    db = clinic_db.create(str(tmp_path / \"c.db\"))\n    assert db_check.check(repo, db) == []\n\n\ndef test_db_check_notices_when_the_database_changes(tmp_path):\n    import sqlite3\n    repo = pipeline.make_base_repo(str(tmp_path))\n    (Path(repo) / \"helpdesk_lookup.py\").write_text(roles.CAREFUL_IMPL)\n    db = clinic_db.create(str(tmp_path / \"c.db\"))\n    con = sqlite3.connect(db)\n    con.execute(\"UPDATE doctors SET days='Tue,Wed' WHERE name='Dr Mehta'\")\n    con.commit(); con.close()\n    out = db_check.check(repo, db)\n    assert any(l.startswith(\"Mon\") for l in out) and any(l.startswith(\"Tue\") for l in out)\n\n\ndef test_db_check_reports_a_feature_that_cannot_be_called(tmp_path):\n    repo = pipeline.make_base_repo(str(tmp_path))                          # base has no doctors_on\n    db = clinic_db.create(str(tmp_path / \"c.db\"))\n    out = db_check.check(repo, db)\n    assert len(out) == 1 and \"could not be called\" in out[0]\n\n\ndef test_budget_math_and_report():\n    b = team_budget.Budget(max_tokens=100_000)\n    b.spend(\"planner\", \"x\", \"a\" * 3500, \"b\" * 700)\n    assert b.rows[0][\"in\"] == 20_000 + 1000 and b.rows[0][\"out\"] == 200\n    expected = 21_000 * 2.0 / 1e6 + 200 * 10.0 / 1e6\n    assert b.rows[0][\"usd\"] == pytest.approx(expected)\n    assert \"TOTAL\" in b.report() and \"ESTIMATE\" in b.report()\n    with pytest.raises(team_budget.BudgetExceeded):\n        for _ in range(10):\n            b.spend(\"coder\", \"y\", \"\", \"\")\n\n\ndef test_tester_role_uses_the_cheap_model():\n    assert team_budget.MODELS[\"tester\"] == \"haiku-5.5\" and team_budget.MODELS[\"coder\"] == \"sonnet-5.5\"\n\n\ndef test_reviewer_rules():\n    ok = {\"gate\": {\"tests\": \"pass\"}, \"outside_owned\": [], \"acceptance\": \"pass\", \"db_mismatches\": [], \"handoff_problems\": [], \"red_green\": \"red-green\"}\n    assert roles.reviewer(ok).approve\n    assert not roles.reviewer({**ok, \"red_green\": \"no-red\"}).approve\n    assert not roles.reviewer({**ok, \"gate\": {\"tests\": \"fail\"}}).approve\n\n\ndef test_plan_has_owned_files_and_markdown():\n    plan, _ = roles.planner(roles.TASK, str(HERE / \"base_project\"))\n    assert plan.owned == [\"helpdesk_lookup.py\", \"test_doctors_on.py\"]\n    assert \"## Files this task owns\" in plan.to_markdown()\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
